func synthRollout(nTurns, encKB int) []byte {
	var sb strings.Builder
	sb.WriteString(`{"type":"session_meta","payload":{"id":"abc"}}` + "\n")
	buf := make([]byte, encKB*1024)
	_, _ = rand.Read(buf)
	enc := base64.StdEncoding.EncodeToString(buf)
	for i := range nTurns {
		sb.WriteString(fmt.Sprintf(`{"type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"please fix the bug in handler %d"}]}}`+"\n", i))
		sb.WriteString(fmt.Sprintf(`{"type":"response_item","payload":{"type":"reasoning","summary":[],"encrypted_content":%q}}`+"\n", enc))
		sb.WriteString(fmt.Sprintf(`{"type":"response_item","payload":{"type":"message","role":"assistant","content":[{"type":"output_text","text":"I fixed handler %d and ran the tests"}]}}`+"\n", i))
	}
	return []byte(sb.String())
}

func BenchmarkScratchRedactOnly(b *testing.B) {
	data := synthRollout(200, 100) // ~27MB
	b.SetBytes(int64(len(data)))
	b.ResetTimer()
	for b.Loop() {
		if _, err := redact.JSONLBytes(data); err != nil {
			b.Fatal(err)
		}
	}
}

func BenchmarkScratchSanitizeThenRedact(b *testing.B) {
	data := synthRollout(200, 100)
	b.SetBytes(int64(len(data)))
	b.ResetTimer()
	for b.Loop() {
		s := codex.SanitizePortableTranscript(data)
		if _, err := redact.JSONLBytes(s); err != nil {
			b.Fatal(err)
		}
	}
}

func TestScratchSizes(t *testing.T) {
	data := synthRollout(200, 100)
	s := codex.SanitizePortableTranscript(data)
	t.Logf("raw=%d bytes (%.1f MB) sanitized=%d bytes (%.1f MB) reduction=%.1f%%",
		len(data), float64(len(data))/1e6, len(s), float64(len(s))/1e6,
		100*(1-float64(len(s))/float64(len(data))))
}
EOF
