func TestScratchTiming(t *testing.T) {
	for _, tc := range []struct{ turns, encKB int }{{20, 100}, {50, 100}, {200, 100}} {
		data := synthRollout(tc.turns, tc.encKB)
		t0 := time.Now()
		if _, err := redact.JSONLBytes(data); err != nil {
			t.Fatal(err)
		}
		rawDur := time.Since(t0)

		t1 := time.Now()
		s := codex.SanitizePortableTranscript(data)
		sanDur := time.Since(t1)
		t2 := time.Now()
		if _, err := redact.JSONLBytes(s); err != nil {
			t.Fatal(err)
		}
		sanRedDur := time.Since(t2)

		t.Logf("size=%.1fMB  redact-only=%v   sanitize=%v + redact=%v (total %v)  speedup=%.0fx",
			float64(len(data))/1e6, rawDur.Round(time.Millisecond),
			sanDur.Round(time.Millisecond), sanRedDur.Round(time.Millisecond),
			(sanDur + sanRedDur).Round(time.Millisecond),
			float64(rawDur)/float64(sanDur+sanRedDur))
	}
}
