// AsTranscriptSanitizer returns the agent as TranscriptSanitizer if it implements
// the interface. Like AsSidecarImageProvider this is a pure local byte transform
// with no external process to negotiate with, so it resolves by type assertion
// alone with no DeclaredCaps gate.
func AsTranscriptSanitizer(ag Agent) (TranscriptSanitizer, bool) {
	if ag == nil {
		return nil, false
	}
	s, ok := ag.(TranscriptSanitizer)
	return s, ok
}

// SanitizeTranscriptForStorage applies the agent's storage sanitizer when it has
// one and returns data unchanged otherwise. This is the entry point every path that
// stores a transcript copy should call BEFORE redaction — see TranscriptSanitizer
// for why the order matters.
//
// Because it is a no-op for agents without the capability and idempotent for those
// with it, it is safe to call on any transcript from any path.
func SanitizeTranscriptForStorage(ag Agent, data []byte) []byte {
	if len(data) == 0 {
		return data
	}
	s, ok := AsTranscriptSanitizer(ag)
	if !ok {
		return data
	}
	sanitized := s.SanitizeTranscriptForStorage(data)
	if sanitized == nil {
		// Defensive: the interface forbids this, but a nil return would silently
		// drop the whole session. Prefer the unsanitized transcript over none.
		return data
	}
	return sanitized
}

