package integration

import (
	"crypto/rand"
	"encoding/base64"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// TestScratchStopHookTimingLargeCodexRollout measures the real Stop hook against a
// large Codex rollout. Throwaway verification, not a committed test.
func TestScratchStopHookTimingLargeCodexRollout(t *testing.T) {
	env := NewFeatureBranchEnv(t)

	buf := make([]byte, 100*1024)
	if _, err := rand.Read(buf); err != nil {
		t.Fatalf("rand: %v", err)
	}
	enc := base64.StdEncoding.EncodeToString(buf)

	sessionID := "codex-timing"
	var sb strings.Builder
	sb.WriteString(`{"timestamp":"2026-01-01T00:00:00Z","type":"session_meta","payload":{"id":"` + sessionID + `","cwd":"` + env.RepoDir + `"}}` + "\n")
	for i := range 200 {
		sb.WriteString(fmt.Sprintf(`{"timestamp":"2026-01-01T00:00:01Z","type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"fix handler %d"}]}}`+"\n", i))
		sb.WriteString(`{"timestamp":"2026-01-01T00:00:02Z","type":"response_item","payload":{"type":"reasoning","summary":[],"encrypted_content":"` + enc + `"}}` + "\n")
		sb.WriteString(fmt.Sprintf(`{"timestamp":"2026-01-01T00:00:03Z","type":"response_item","payload":{"type":"message","role":"assistant","content":[{"type":"output_text","text":"fixed handler %d"}]}}`+"\n", i))
	}
	rollout := sb.String()

	transcriptPath := filepath.Join(env.RepoDir, ".entire", "tmp", "codex-rollout.jsonl")
	if err := os.MkdirAll(filepath.Dir(transcriptPath), 0o755); err != nil {
		t.Fatalf("mkdir: %v", err)
	}
	if err := os.WriteFile(transcriptPath, []byte(rollout), 0o644); err != nil {
		t.Fatalf("write rollout: %v", err)
	}

	hook := codexHooker(t, env.RepoDir, sessionID, transcriptPath)
	hook("user-prompt-submit", map[string]any{
		"prompt": "fix the handlers", "hook_event_name": "UserPromptSubmit",
	})
	env.WriteFile("feature.txt", "hi\n")
	applyPatchHook(hook, "call_1", "*** Begin Patch\n*** Add File: feature.txt\n+hi\n*** End Patch\n")

	start := time.Now()
	hook("stop", map[string]any{"hook_event_name": "Stop"})
	elapsed := time.Since(start)

	stored, ok := findShadowSessionTranscript(t, env.RepoDir, env.GetShadowBranchName())
	if !ok {
		t.Fatal("no shadow transcript")
	}

	t.Logf("raw rollout = %.1f MB", float64(len(rollout))/1e6)
	t.Logf("stored shadow blob = %.1f KB (%.2f%% of raw)",
		float64(len(stored))/1e3, 100*float64(len(stored))/float64(len(rollout)))
	t.Logf("Stop hook wall time = %v", elapsed.Round(time.Millisecond))
}

